//! The same deterministic fixture is run on unmodified BASE and the candidate.
//! The checked-in bytes are generated by BASE, not by the compact implementation.
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, UNIX_EPOCH};

use mosdns_upstream_core::TransportCancellation;
use tokio::sync::{Mutex as AsyncMutex, Semaphore};

use super::{AuditPersistenceFaults, Request, dispatch};
use crate::observer::{
    AnswerDetailsStatus, AuditAnswer, AuditClock, AuditRecord, CacheStatus, FailureProvenance,
    QueryObserver, QueryTerminalOutcome, QueryTransport, ResponseDetails, ResponseFlags,
    ResponseSource, ResponseState, TerminalObservation, UpstreamAttemptOutcome,
    UpstreamAttemptRecord, UpstreamDiagnosticAttempt, UpstreamDiagnosticBranch,
    UpstreamDiagnosticSelected, UpstreamDiagnostics, UpstreamTransport,
};

fn fixture(index: u32) -> AuditRecord {
    let peer: SocketAddr = "[2001:db8::53]:853".parse().unwrap();
    AuditRecord {
        timestamp: UNIX_EPOCH + Duration::from_secs(100 + u64::from(index)),
        client_addr: if index % 2 == 0 {
            "192.0.2.1:53000"
        } else {
            "[2001:db8::1]:53001"
        }
        .parse()
        .unwrap(),
        transport: if index % 2 == 0 {
            QueryTransport::Udp
        } else {
            QueryTransport::Tcp
        },
        qname: [
            ".",
            "a.example.",
            "alias.example.",
            "escaped\\046name.example.",
        ][index as usize % 4]
            .to_owned(),
        qtype: [1, 28, 65000, 5][index as usize % 4],
        qclass: 1,
        trace_id: format!("n-11111111111111111111111111111111-{index:016x}"),
        elapsed: Duration::from_micros(100 + u64::from(index % 4)),
        terminal_outcome: QueryTerminalOutcome::SendSucceeded,
        response: ResponseState::Dns {
            rcode: u16::try_from(index % 4).unwrap(),
            source: ResponseSource::Upstream("provider".to_owned()),
        },
        response_details: ResponseDetails {
            rcode: u16::try_from(index % 4).unwrap(),
            flags: ResponseFlags {
                aa: index % 2 == 0,
                tc: index % 3 == 0,
                ra: true,
            },
            answers: vec![
                AuditAnswer {
                    rrtype: 1,
                    ttl: 60 + index,
                    data: "192.0.2.8".to_owned(),
                },
                AuditAnswer {
                    rrtype: 5,
                    ttl: index,
                    data: "alias.example.".to_owned(),
                },
                AuditAnswer {
                    rrtype: 65000,
                    ttl: 0,
                    data: "\\000 arbitrary 原始".to_owned(),
                },
            ],
            answer_details_status: [
                AnswerDetailsStatus::Complete,
                AnswerDetailsStatus::RawRdata,
                AnswerDetailsStatus::DecodeError,
            ][index as usize % 3],
            answer_decode_error: (index % 3 == 2).then(|| "truncated answer".to_owned()),
        },
        cache_status: if index % 2 == 0 {
            CacheStatus::Hit
        } else {
            CacheStatus::Miss
        },
        final_sequence: Some("sequence".to_owned()),
        matched_group: None,
        domain_set: match index % 3 {
            0 => None,
            1 => Some(String::new()),
            _ => Some("白名单|订阅代理".to_owned()),
        },
        effective_tag: Some("白名单".to_owned()),
        matched_rule_source: Some("provider:测试".to_owned()),
        final_upstream: Some("domestic".to_owned()),
        upstream_targets: Some("tls://resolver.example:853".to_owned()),
        selected_upstream: Some(peer.to_string()),
        upstream_attempts: vec![UpstreamAttemptRecord {
            upstream: "provider".to_owned(),
            outcome: UpstreamAttemptOutcome::Response,
        }],
        upstream_diagnostics: (index % 3 != 0).then(|| UpstreamDiagnostics {
            schema_version: if index % 2 == 0 { 1 } else { 2 },
            branches: vec![
                UpstreamDiagnosticBranch {
                    id: 0,
                    parent_id: None,
                    role: "root".to_owned(),
                    policy: None,
                    qtype: 1,
                    decision: "response".to_owned(),
                },
                UpstreamDiagnosticBranch {
                    id: 1,
                    parent_id: Some(0),
                    role: "child".to_owned(),
                    policy: Some("prefer_ipv4".to_owned()),
                    qtype: 28,
                    decision: "canceled".to_owned(),
                },
            ],
            selected: Some(UpstreamDiagnosticSelected {
                branch_id: Some(0),
                entry: "provider".to_owned(),
                peer,
                transport: UpstreamTransport::Tls,
            }),
            attempts: [
                UpstreamAttemptOutcome::Response,
                UpstreamAttemptOutcome::TimedOut,
                UpstreamAttemptOutcome::Failed,
                UpstreamAttemptOutcome::Canceled,
                UpstreamAttemptOutcome::Interrupted,
            ]
            .into_iter()
            .enumerate()
            .map(|(ordinal, outcome)| UpstreamDiagnosticAttempt {
                ordinal,
                branch_id: Some(ordinal % 2),
                qtype: Some(28),
                entry: format!("entry-{ordinal}"),
                peer: (ordinal % 2 == 0).then_some(peer),
                transport: (ordinal % 2 == 0).then_some(UpstreamTransport::Tls),
                outcome,
            })
            .collect(),
        }),
        failure_provenance: Some(FailureProvenance::UpstreamTimeout {
            upstream: "failed-peer".to_owned(),
        }),
    }
}

#[test]
fn retained_audit_api_response_bytes_equal_base_fixture() {
    let host = crate::HostAssembly::from_config(
        crate::compile_yaml(include_str!(
            "../../../../tests/phase5a-baseline/configs/forward-udp.yaml"
        ))
        .unwrap(),
    )
    .unwrap();
    let observer = Arc::new(QueryObserver::new(true, ["provider".to_owned()], 8));
    for index in 0..12 {
        observer.admit_query();
        observer.record_terminal(TerminalObservation::default(), |_| fixture(index));
    }
    let clock: Arc<dyn AuditClock> = Arc::new(crate::AuditTestClock::new(
        UNIX_EPOCH + Duration::from_secs(3700),
    ));
    let persist = Arc::new(AsyncMutex::new(()));
    let faults = AuditPersistenceFaults::default();
    let slots = Arc::new(Semaphore::new(2));
    let shutdown = TransportCancellation::new();
    let mut actual = Vec::new();
    host.block_on(async {
        for (method, target, body) in [
            ("GET", "/api/v1/audit/status", ""),
            ("GET", "/api/v1/audit/capacity", ""),
            ("GET", "/api/v2/audit/stats", ""),
            ("GET", "/api/v2/audit/stats/windows", ""),
            ("GET", "/api/v2/audit/logs?limit=3&page=1", ""),
            ("GET", "/api/v2/audit/logs?limit=3&page=2", ""),
            ("GET", "/api/v2/audit/logs?q=0000000000000008", ""),
            ("GET", "/api/v2/audit/logs?answer_ip=192.0.2.8", ""),
            ("GET", "/api/v2/audit/logs?cname=alias.example", ""),
            ("GET", "/api/v2/audit/logs/domain?domain=a.example", ""),
            ("GET", "/api/v2/audit/rank/domain?limit=3", ""),
            ("GET", "/api/v2/audit/rank/client", ""),
            ("GET", "/api/v2/audit/rank/domain_set", ""),
            ("GET", "/api/v2/audit/rank/effective", ""),
            ("GET", "/api/v2/audit/rank/slowest?limit=8", ""),
            ("POST", "/api/v1/audit/capacity", "{\"capacity\":400001}"),
            ("POST", "/api/v1/audit/stop", "{}"),
            ("GET", "/api/v1/audit/status", ""),
            ("POST", "/api/v1/audit/start", "{}"),
            ("GET", "/api/v1/audit/status", ""),
            ("POST", "/api/v1/audit/clear", "{}"),
            ("GET", "/api/v2/audit/stats", ""),
            ("GET", "/api/v2/audit/stats/windows", ""),
            ("GET", "/api/v2/audit/logs", ""),
        ] {
            let response = dispatch(
                None,
                None,
                host.config(),
                host.cache(),
                &observer,
                None,
                &persist,
                &faults,
                &clock,
                &slots,
                &shutdown,
                &Request {
                    method: method.to_owned(),
                    target: target.to_owned(),
                    content_type: None,
                    if_none_match: None,
                    config_generation: None,
                    config_generation_duplicate: false,
                    body: body.as_bytes().to_vec(),
                },
            )
            .await;
            serde_json::to_writer(
                &mut actual,
                &(
                    method,
                    target,
                    response.status,
                    response.content_type,
                    response.headers,
                    String::from_utf8(response.body).unwrap(),
                ),
            )
            .unwrap();
            actual.push(b'\n');
        }
    });
    // Used only when generating the original BASE artifact in the disposable
    // source tree. The assertion always runs, including on the candidate.
    if let Ok(path) = std::env::var("FIVE_D_BASE_API_BYTES") {
        std::fs::write(path, &actual).unwrap();
    }
    assert!(
        actual == include_bytes!("../../tests/fixtures/audit-retention-base.jsonl"),
        "audit response bytes differ from BASE characterization"
    );
}
